source_url":null},{"name":"Zilog, Inc.","slug":"zilog","domain":null,"description":null,"sector":null,"hq":null,"status":null,"invested_year":null,"exit_year":null,"fund_name":null,"source_url":"https://warburgpincus.com/warburg-pincus-portfolio/","deal_value":null,"deal_currency":null,"deal_value_basis":null,"stake_pct":null,"co_investors":[],"deal_source_url":null},{"name":"Zimperium, Inc.","slug":"zimperium","domain":null,"description":null,"sector":null,"hq":null,"status":null,"invested_year":2016,"exit_year":null,"fund_name":null,"source_url":"https://warburgpincus.com/2016/06/07/zimperium-closes-25-million-series-c-funding-led-by-warburg-pincus/","deal_value":null,"deal_currency":null,"deal_value_basis":null,"stake_pct":null,"co_investors":[],"deal_source_url":null},{"name":"Ziroom","slug":"ziroom","domain":"ziroom.com","description":"Ziroom is a technology company that offers high-quality apartments and services, and creates communities for its tenants through an innovative O2O business model.","sector":"Technology, Media & Telecommunications, Technology, Media & Telecommunications","hq":null,"status":"current","invested_year":2018,"exit_year":null,"fund_name":null,"source_url":"https://warburgpincus.com/investments/ziroom/","deal_value":null,"deal_currency":null,"deal_value_basis":null,"stake_pct":null,"co_investors":[],"deal_source_url":null},{"name":"ZSM","slug":"zsm","domain":"zsmyy.com","description":"Founded in 2006, ZSM is a leading eye care company in China.","sector":"Healthcare","hq":null,"status":"current","invested_year":2021,"exit_year":null,"fund_name":null,"source_url":"https://warburgpincus.com/investments/zsm/","deal_value":null,"deal_currency":null,"deal_value_basis":null,"stake_pct":null,"co_investors":[],"deal_source_url":null},{"name":"ZTO Express (Cayman) Inc.","slug":"zto-express-cayman","domain":null,"description":null,"sector":null,"hq":null,"status":null,"invested_year":null,"exit_year":null,"fund_name":null,"source_url":"https://war